import { Method, ClientPrefix } from "../../http-api/index.ts";
import type { MatrixHttpApi, IHttpOpts } from "../../http-api/index.ts";
import type { IKeyValueStore } from "../../store/KeyValueStore.ts";
import type { ILoginFlowsResponse, LoginRequest, LoginResponse } from "../../@types/auth.ts";
import type { EmptyObject } from "../../@types/common.ts";

export interface AuthManagerEvents {
    login: LoginResponse;
    logout: void;
    error: Error;
}

export interface WhoamiResponse {
    user_id: string;
    is_guest: boolean;
    device_id?: string;
}

export type IdServerUnbindResult = "no-support" | "success";

export type LoginTokenPostResponse = {
    access_token: string;
    token_type: string;
    expires_in: number;
    refresh_token?: string;
    user_id: string;
    device_id?: string;
};

export type SSOAction = "redirect" | "fail";

export type AuthDict = Record<string, unknown>;

export class AuthManager {
    private accessToken: string | null = null;
    private refreshToken: string | null = null;
    private userId: string | null = null;
    private expiresAt: number = 0;

    public constructor(
        private http: MatrixHttpApi<IHttpOpts>,
        private store: IKeyValueStore,
    ) {
        this.loadCredentials();
    }

    public async loginFlows(): Promise<ILoginFlowsResponse> {
        return this.http.request(Method.Get, "/login");
    }

    public async loginRequest(data: LoginRequest): Promise<LoginResponse> {
        const response = await this.http.authedRequest<LoginResponse>(Method.Post, "/login", undefined, data);

        if (response.access_token && response.user_id) {
            this.accessToken = response.access_token;
            this.refreshToken = response.refresh_token || null;
            this.userId = response.user_id;
            this.expiresAt = response.expires_in_ms ? Date.now() + response.expires_in_ms : 0;

            this.http.opts.accessToken = response.access_token;
            await this.saveCredentials();
        }

        return response;
    }

    public async loginWithPassword(user: string, password: string): Promise<LoginResponse> {
        return this.loginRequest({
            type: "m.login.password",
            user,
            password,
        });
    }

    public async loginWithToken(token: string): Promise<LoginResponse> {
        return this.loginRequest({
            type: "m.login.token",
            token,
        });
    }

    public async logout(stopClient = false): Promise<void> {
        if (stopClient) {
            this.http.abort();
        }

        await this.http.authedRequest(Method.Post, "/logout");
        this.clearCredentials();
    }

    public async logoutAll(stopClient = false): Promise<void> {
        if (stopClient) {
            this.http.abort();
        }

        await this.http.authedRequest(Method.Post, "/logout/all");
        this.clearCredentials();
    }

    public async deactivateAccount(
        auth?: AuthDict,
        erase?: boolean,
    ): Promise<{ id_server_unbind_result: IdServerUnbindResult }> {
        const body: Record<string, unknown> = {};
        if (auth) {
            body.auth = auth;
        }
        if (erase !== undefined) {
            body.erase = erase;
        }

        return this.http.authedRequest(Method.Post, "/account/deactivate", undefined, body);
    }

    public async requestLoginToken(auth?: AuthDict): Promise<LoginTokenPostResponse> {
        const body: Record<string, unknown> = { auth };
        return this.http.authedRequest<LoginTokenPostResponse>(Method.Post, "/login/get_token", undefined, body, {
            prefix: ClientPrefix.V1,
        });
    }

    public getFallbackAuthUrl(loginType: string, authSessionId: string): string {
        return this.http.getUrl("/auth/$loginType/fallback/web", {
            $loginType: loginType,
            session: authSessionId,
        }).href;
    }

    public getSsoLoginUrl(redirectUrl: string, loginType = "sso", idpId?: string, action?: SSOAction): string {
        let url = "/login/" + loginType + "/redirect";
        if (idpId) {
            url += "/" + idpId;
        }

        const params: Record<string, string | undefined> = {
            redirectUrl,
            "org.matrix.msc3824.action": action,
        };

        return this.http.getUrl(url, params).href;
    }

    public getCasLoginUrl(redirectUrl: string): string {
        return this.getSsoLoginUrl(redirectUrl, "cas");
    }

    public async setPassword(authDict: AuthDict, newPassword: string, logoutDevices?: boolean): Promise<EmptyObject> {
        const path = "/account/password";
        return this.http.authedRequest(Method.Post, path, undefined, {
            auth: authDict,
            new_password: newPassword,
            logout_devices: logoutDevices,
        });
    }

    public async get3PIDs(): Promise<Record<string, unknown>> {
        return this.http.authedRequest(Method.Get, "/account/3pid");
    }

    public async add3PID(
        clientSecret: string,
        sid: string,
        auth?: AuthDict,
        idServer?: string,
        bind?: boolean,
    ): Promise<EmptyObject> {
        const path = bind ? "/account/3pid/bind" : "/account/3pid/add";
        const body: Record<string, unknown> = {
            client_secret: clientSecret,
            sid,
        };
        if (auth) {
            body.auth = auth;
        }
        if (idServer) {
            body.id_server = idServer;
        }

        return this.http.authedRequest(Method.Post, path, undefined, body);
    }

    public async delete3PID(medium: string, address: string, idServer?: string): Promise<EmptyObject> {
        const path = "/account/3pid/delete";
        const body: Record<string, unknown> = {
            medium,
            address,
        };
        if (idServer) {
            body.id_server = idServer;
        }

        return this.http.authedRequest(Method.Post, path, undefined, body);
    }

    public async unbind3PID(medium: string, address: string, idServer?: string): Promise<EmptyObject> {
        const path = "/account/3pid/unbind";
        const body: Record<string, unknown> = {
            medium,
            address,
        };
        if (idServer) {
            body.id_server = idServer;
        }

        return this.http.authedRequest(Method.Post, path, undefined, body);
    }

    public async whoami(): Promise<WhoamiResponse> {
        return this.http.authedRequest(Method.Get, "/account/whoami");
    }

    public getAccessToken(): string | null {
        return this.accessToken;
    }

    public getUserId(): string | null {
        return this.userId;
    }

    public isLoggedIn(): boolean {
        return this.accessToken !== null && (this.expiresAt === 0 || Date.now() < this.expiresAt);
    }

    public async refreshAccessToken(): Promise<void> {
        if (!this.refreshToken) {
            throw new Error("No refresh token available");
        }

        const response = await this.http.authedRequest<{ access_token: string; expires_in: number }>(
            Method.Post,
            "/tokenrefresh",
            undefined,
            { refresh_token: this.refreshToken },
        );

        this.accessToken = response.access_token;
        this.expiresAt = Date.now() + response.expires_in * 1000;
        this.http.opts.accessToken = response.access_token;
        await this.saveCredentials();
    }

    private async saveCredentials(): Promise<void> {
        await this.store.setItem("auth_credentials", {
            accessToken: this.accessToken,
            refreshToken: this.refreshToken,
            userId: this.userId,
            expiresAt: this.expiresAt,
        });
    }

    private async loadCredentials(): Promise<void> {
        const credentials = await this.store.getItem<{
            accessToken?: string | null;
            refreshToken?: string | null;
            userId?: string | null;
            expiresAt?: number;
        }>("auth_credentials");
        if (credentials) {
            this.accessToken = credentials.accessToken ?? null;
            this.refreshToken = credentials.refreshToken ?? null;
            this.userId = credentials.userId ?? null;
            this.expiresAt = credentials.expiresAt ?? 0;

            if (this.accessToken) {
                this.http.opts.accessToken = this.accessToken;
            }
        }
    }

    private clearCredentials(): void {
        this.accessToken = null;
        this.refreshToken = null;
        this.userId = null;
        this.expiresAt = 0;
        this.http.opts.accessToken = undefined;
        this.store.deleteItem("auth_credentials");
    }
}
